<script lang="ts">
  import {untrack} from 'svelte';
  import ProfileValueEditor from './ProfileValueEditor.svelte';
  import Icon from './Icon.svelte';
  import {processingNodeError} from './profile-processing';
  import {processingDerivedNode} from './profile-transform-drafts';
  import type{DeepReadonly,ProfileOperation,ProfileProcessingNode,ProfileValue}from'./profiles';
  let {node,change}:{node:DeepReadonly<ProfileProcessingNode>;change:(node:ProfileProcessingNode)=>void|boolean}=$props();
  const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
  let draft=$state<ProfileProcessingNode>(copy(untrack(()=>node)) as ProfileProcessingNode),signature=$state(JSON.stringify(untrack(()=>node)));
  let compactError=$state('');
  const error=$derived(compactError);
  const firstOutput=$derived(draft.outputs[0]?.contract);
  const outputSchema=$derived(firstOutput&&'schema'in firstOutput?firstOutput.schema:null);
  $effect(()=>{const next=JSON.stringify(node);if(next!==signature){signature=next;draft=copy(node) as ProfileProcessingNode;compactError='';}});
  let compactReady=false;
  $effect(()=>{const next=JSON.stringify(draft);if(!compactReady){compactReady=true;signature=next;return;}if(next===signature)return;untrack(autoSave);});
  const heading=(key:string)=>key==='factor'?'Multiply by':key==='centerPercent'?'Center (%)':key==='deadzonePercent'?'Deadzone (%)':key.replace(/([A-Z])/g,' $1').replace(/^./,letter=>letter.toUpperCase());
  function autoSave():boolean{let candidate:ProfileProcessingNode;try{candidate=processingDerivedNode(draft);}catch(issue){compactError=issue instanceof Error?issue.message:String(issue);return false;}const issue=processingNodeError(candidate);if(issue){compactError=issue;return false;}signature=JSON.stringify(draft);compactError='';if(change(copy(candidate))===false){compactError='This parameter change could not be applied.';return false;}return true;}
  function field(key:string,value:unknown){const outputs=draft.operation.kind==='declare-quantity'&&key==='unit'&&typeof value==='string'?draft.outputs.map(port=>'schema'in port.contract&&(port.contract.schema.type==='integer'||port.contract.schema.type==='number')?{...port,contract:{...port.contract,schema:{...port.contract.schema,unit:value}}}:port):draft.outputs;draft={...draft,operation:{...draft.operation,[key]:value} as ProfileOperation,outputs};}
  function ruleField(key:string,value:unknown){if(draft.operation.kind==='builtin')draft={...draft,operation:{...draft.operation,rule:{...draft.operation.rule,[key]:value} as typeof draft.operation.rule}};}
  function addParameter(){if(draft.operation.kind!=='script')return;let n=1;while(Object.hasOwn(draft.operation.parameters,`parameter-${n}`))n++;field('parameters',{...draft.operation.parameters,[`parameter-${n}`]:false});}
  function parameter(id:string,value:Exclude<ProfileValue,null>){if(draft.operation.kind==='script')field('parameters',{...draft.operation.parameters,[id]:value});}
  function parameterName(old:string,id:string){if(draft.operation.kind!=='script')return;field('parameters',Object.fromEntries(Object.entries(draft.operation.parameters).map(([key,value])=>[key===old?id:key,value])));}
  function priority(index:number,delta:number){if(draft.operation.kind!=='priority')return;const order=[...draft.operation.order],other=index+delta;if(other<0||other>=order.length)return;[order[index],order[other]]=[order[other],order[index]];field('order',order);}
  function addBuiltinCurvePoint(){if(draft.operation.kind!=='builtin'||draft.operation.rule.kind!=='axis')return;const contract=draft.inputs[0]?.contract,schema=contract&&'schema'in contract?contract.schema:null;if(!schema||schema.type!=='integer'&&schema.type!=='number')return;const points=[...draft.operation.rule.curve];if(points.length<2){ruleField('curve',[{input:schema.min,output:schema.min},{input:schema.max,output:schema.max}]);return;}let index=0;for(let i=1;i<points.length-1;i++)if(points[i+1].input-points[i].input>points[index+1].input-points[index].input)index=i;points.splice(index+1,0,{input:Math.floor((points[index].input+points[index+1].input)/2),output:Math.floor((points[index].output+points[index+1].output)/2)});ruleField('curve',points);}
</script>
<section class="processing-editor compact" aria-label="Parameters">
  {#if draft.operation.kind==='declare-quantity'}
    <label>Quantity definition<input value={draft.operation.quantity} maxlength="128" oninput={event=>field('quantity',event.currentTarget.value)}/></label>
    <label>Declared unit<input value={draft.operation.unit} maxlength="128" oninput={event=>field('unit',event.currentTarget.value)}/></label>
  {:else if draft.operation.kind==='hat-direction'}
    <label>Cardinal direction<select aria-label="Hat cardinal direction" value={draft.operation.direction} onchange={event=>field('direction',event.currentTarget.value)}>{#each ['up','right','down','left']as direction}<option value={direction}>{direction}</option>{/each}</select></label>
    <label class="check"><input type="checkbox" checked={draft.operation.diagonals} onchange={event=>field('diagonals',event.currentTarget.checked)}/>Include adjacent diagonal positions</label>
  {:else if draft.operation.kind==='constant'&&outputSchema}<ProfileValueEditor schema={outputSchema} value={draft.operation.value} label="Constant" change={value=>{if(value!==null)field('value',value);}}/>
  {:else if draft.operation.kind==='select'&&outputSchema}<ProfileValueEditor schema={outputSchema} value={draft.operation.whenTrue} label="When true" change={value=>{if(value!==null)field('whenTrue',value);}}/><ProfileValueEditor schema={outputSchema} value={draft.operation.whenFalse} label="When false" change={value=>{if(value!==null)field('whenFalse',value);}}/>
  {:else if draft.operation.kind==='fallback'&&outputSchema}{#each ['unknown','stale','unavailable'] as key}<ProfileValueEditor schema={outputSchema} value={draft.operation[key as 'unknown'|'stale'|'unavailable']} label={heading(key)} change={value=>{if(value!==null)field(key,value);}}/>{/each}
  {:else if draft.operation.kind==='script'}
    <label class="wide">Typed Rhai source<textarea rows="12" value={draft.operation.source} oninput={event=>field('source',event.currentTarget.value)} spellcheck="false"></textarea></label>
    {#each Object.entries(draft.operation.parameters) as [key,value]}<fieldset class="wide"><label>Parameter name<input value={key} oninput={event=>parameterName(key,event.currentTarget.value)}/></label><label>Type<select value={typeof value} onchange={event=>parameter(key,event.currentTarget.value==='boolean'?false:event.currentTarget.value==='number'?0:'')}><option value="boolean">Boolean</option><option value="number">Number</option><option value="string">Text</option></select></label><ProfileValueEditor schema={typeof value==='boolean'?{type:'boolean'}:typeof value==='number'?{type:'number',min:-Number.MAX_SAFE_INTEGER,max:Number.MAX_SAFE_INTEGER,unit:null}:{type:'text',maxBytes:4096,encoding:'utf8'}} {value} label="Parameter value" change={next=>{if(next!==null)parameter(key,next);}}/><button class="text-button" onclick={()=>{if(draft.operation.kind==='script')field('parameters',Object.fromEntries(Object.entries(draft.operation.parameters).filter(([id])=>id!==key)));}}><Icon name="trash" size={13}/>Remove parameter</button></fieldset>{/each}<button class="secondary-button" disabled={Object.keys(draft.operation.parameters).length>=64} onclick={addParameter}><Icon name="plus" size={14}/>Add parameter</button>
  {:else if draft.operation.kind==='priority'}<ol class="priority">{#each draft.operation.order as id,index (id)}<li><code>{id}</code><button aria-label={`Raise ${id} priority`} disabled={index===0} onclick={()=>priority(index,-1)}><span class="up"><Icon name="chevron" size={13}/></span></button><button aria-label={`Lower ${id} priority`} disabled={index===draft.inputs.length-1} onclick={()=>priority(index,1)}><span class="down"><Icon name="chevron" size={13}/></span></button></li>{/each}</ol>
  {:else}
    {#each Object.entries(draft.operation).filter(([key])=>!['kind','rule','inputs','points','clamp'].includes(key)) as [key,value]}
      {#if typeof value==='number'}<label>{heading(key)}<input aria-label={heading(key)} type="number" min={key==='centerPercent'||key==='deadzonePercent'?0:undefined} max={key==='centerPercent'||key==='deadzonePercent'?100:undefined} value={value} step="any" oninput={event=>field(key,Number(event.currentTarget.value))}/></label>
      {:else if typeof value==='string'}<label>{heading(key)}{#if ['rounding','comparison','edge','overflow'].includes(key)}<select aria-label={heading(key)} value={value} onchange={event=>field(key,event.currentTarget.value)}>{#each key==='rounding'?['none','nearest','floor','ceil','truncate']:key==='comparison'?['greater','greater-equal','less','less-equal','equal','not-equal']:key==='edge'?['rising','falling','change']:['reject','truncate'] as option}<option value={option}>{option}</option>{/each}</select>{:else}<input aria-label={heading(key)} value={value} oninput={event=>field(key,event.currentTarget.value)}/>{/if}</label>{/if}
    {/each}
    {#if draft.operation.kind==='unit-convert'}<label class="check"><input type="checkbox" checked={draft.operation.clamp??false} onchange={event=>field('clamp',event.currentTarget.checked)}/>Clamp to output range</label>{/if}
    {#if draft.operation.kind==='curve'}{#each draft.operation.points as point,index}<div class="pair"><label>Input {index+1}<input type="number" step="any" value={point.input} oninput={event=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.map((p,i)=>i===index?{...p,input:Number(event.currentTarget.value)}:p));}}/></label><label>Output {index+1}<input type="number" step="any" value={point.output} oninput={event=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.map((p,i)=>i===index?{...p,output:Number(event.currentTarget.value)}:p));}}/></label><button class="text-button" onclick={()=>{if(draft.operation.kind==='curve')field('points',draft.operation.points.filter((_,i)=>i!==index));}}><Icon name="trash" size={13}/>Remove point</button></div>{/each}<button class="secondary-button" disabled={draft.operation.points.length>=32} onclick={()=>{if(draft.operation.kind==='curve'){const last=draft.operation.points.at(-1)!;field('points',[...draft.operation.points,{input:last.input+1,output:last.output}]);}}}><Icon name="plus" size={14}/>Add curve point</button>{/if}
    {#if draft.operation.kind==='builtin'}{#each Object.entries(draft.operation.rule).filter(([key])=>!['kind','curve','steps'].includes(key)) as [key,value]}{#if typeof value==='boolean'}<label class="check"><input type="checkbox" checked={value} onchange={event=>ruleField(key,event.currentTarget.checked)}/>{heading(key)}</label>{:else if typeof value==='number'}<label>{heading(key)} (µs for timing)<input type="number" value={value} oninput={event=>ruleField(key,Number(event.currentTarget.value))}/></label>{:else if typeof value==='string'}<label>{heading(key)}<input value={value} oninput={event=>ruleField(key,event.currentTarget.value)}/></label>{/if}{/each}
      {#if draft.operation.rule.kind==='axis'}{#each draft.operation.rule.curve as point,index}<div class="pair"><label>Input {index+1}<input type="number" value={point.input} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.map((p,i)=>i===index?{...p,input:Number(event.currentTarget.value)}:p));}}/></label><label>Output {index+1}<input type="number" value={point.output} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.map((p,i)=>i===index?{...p,output:Number(event.currentTarget.value)}:p));}}/></label><button class="text-button" onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='axis')ruleField('curve',draft.operation.rule.curve.filter((_,i)=>i!==index));}}><Icon name="trash" size={13}/>Remove curve point</button></div>{/each}<button class="secondary-button" disabled={draft.operation.rule.curve.length>=32} onclick={addBuiltinCurvePoint}><Icon name="plus" size={14}/>Add native-axis curve point</button>{/if}
      {#if draft.operation.rule.kind==='macro'}{#each draft.operation.rule.steps as step,index}<div class="pair"><label>After (µs)<input type="number" min="0" max="60000000" value={step.afterUs} oninput={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.map((p,i)=>i===index?{...p,afterUs:Number(event.currentTarget.value)}:p));}}/></label><label class="check"><input type="checkbox" checked={step.pressed} onchange={event=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.map((p,i)=>i===index?{...p,pressed:event.currentTarget.checked}:p));}}/>Pressed</label><button class="text-button" onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',draft.operation.rule.steps.filter((_,i)=>i!==index));}}><Icon name="trash" size={13}/>Remove step</button></div>{/each}<button class="secondary-button" disabled={draft.operation.rule.steps.length>=16} onclick={()=>{if(draft.operation.kind==='builtin'&&draft.operation.rule.kind==='macro')ruleField('steps',[...draft.operation.rule.steps,{afterUs:(draft.operation.rule.steps.at(-1)?.afterUs??0)+100000,pressed:false}]);}}><Icon name="plus" size={14}/>Add macro step</button>{/if}
    {/if}
  {/if}
  {#if error}<p class="error" role="status">{error}</p>{/if}
</section>
<style>
  .processing-editor{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,140px),1fr));align-items:start;gap:4px 8px;min-width:0}.processing-editor label{display:grid;gap:4px;min-width:0;margin:0;font-size:var(--ui-text-size);color:var(--muted)}.processing-editor input:not([type="checkbox"]),.processing-editor select,.processing-editor textarea{width:100%;min-width:0;box-sizing:border-box;background:var(--input-bg);border:1px solid var(--line);border-radius:5px;padding:4px 8px;color:var(--text);font-size:var(--ui-text-size);min-height:30px;height:30px}.processing-editor textarea{height:auto;min-height:100px;font-family:monospace;line-height:var(--ui-line-height)}.check{display:flex!important;align-items:center;gap:7px!important}.pair{display:grid;grid-column:1/-1;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.pair button{grid-column:1/-1}.processing-editor button{font-size:var(--ui-action-size)}.processing-editor fieldset{grid-column:1/-1;border:1px solid var(--line);padding:10px;margin:0;min-width:0}.processing-editor .error{grid-column:1/-1;margin:2px 0;font-size:var(--ui-text-size);color:#d3a078;line-height:var(--ui-line-height)}.priority{grid-column:1/-1;padding-left:16px;font-size:var(--ui-text-size)}.priority li{padding:2px 0}.priority button{margin-left:8px;padding:4px;background:var(--surface-raised);color:var(--soft)}.down{transform:rotate(90deg)}.up{transform:rotate(-90deg)}
</style>
